@router.get("/images/list")
async def api_list_images(request: Request):
    """
    List all generated images with metadata.

    Response:
    {
        "status": "success",
        "images": [
            {
                "id": "hash123",
                "filename": "hash123.png",
                "path": "images/generated/hash123.png",
